// src/pages/Home.jsx
import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { useUI } from "../context/UIContext";
import { introText } from "../constants/sdm"; // 引入你原本寫在 sdm.js 裡的開頭台詞
import Input from "../components/common/Input";
import Button from "../components/common/Button";
import styles from "../Home.module.css";

const Home = () => {
  const navigate = useNavigate();
  const { setHeroData, setAllAnswers } = useUI();
  const videoRef = useRef(null);

  // 互動狀態
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [displayedSubtitle, setDisplayedSubtitle] = useState("");
  const [formData, setFormData] = useState({
    userName: "",
    birthday: "",
  });

  // 設定原本的 Hero 頂部資訊區
  useEffect(() => {
    setHeroData({
      imageUrl: "/assets/helperinside.png", // 配合你的專案 assets 路徑
      title: "乳房手術方式輔助決策小幫手",
      description:
        "歡迎使用！我將一步一步陪您釐清，幫助您做出最適合自己的決定。",
    });
  }, [setHeroData]);

  // 組件卸載時，確保語音停止
  useEffect(() => {
    return () => {
      if (window.speechSynthesis) {
        window.speechSynthesis.cancel();
      }
    };
  }, []);

  // 語音 API 串接與打字機同步邏輯
  const handleVoiceIntro = () => {
    if (!window.speechSynthesis) {
      alert("您的瀏覽器暫不支援語音播放功能");
      return;
    }

    // 取消先前可能還在唸的語音
    window.speechSynthesis.cancel();

    // 將 sdm.js 中的 introText 轉為純文字傳給語音 API
    const pureText = introText.replace(/<[^>]*>/g, "").trim();

    const utterance = new SpeechSynthesisUtterance(pureText);
    utterance.lang = "zh-TW";
    utterance.rate = 1.0;

    utterance.onstart = () => {
      setIsSpeaking(true);
      if (videoRef.current) {
        videoRef.current
          .play()
          .catch((err) => console.log("影片播放受阻：", err));
      }
      startTypewriter(pureText);
    };

    utterance.onend = () => {
      setIsSpeaking(false);
      if (videoRef.current) {
        videoRef.current.pause(); // 唸完後助理暫停說話
      }
    };

    utterance.onerror = () => {
      setIsSpeaking(false);
    };

    window.speechSynthesis.speak(utterance);
  };

  // 逐字浮現字幕特效
  const startTypewriter = (text) => {
    let currentIdx = 0;
    setDisplayedSubtitle("");
    const interval = setInterval(() => {
      if (currentIdx < text.length) {
        setDisplayedSubtitle((prev) => prev + text.charAt(currentIdx));
        currentIdx++;
      } else {
        clearInterval(interval);
      }
    }, 60); // 調整打字速度
  };

  // 建立跳轉處理函式（原本的邏輯完整保留）
  const handleStart = () => {
    if (!formData.userName || !formData.birthday) {
      alert("請填寫完整資料後再開始");
      return;
    }

    // 關閉語音
    if (window.speechSynthesis) {
      window.speechSynthesis.cancel();
    }

    setAllAnswers((prev) => ({
      ...prev,
      userName: formData.userName,
      birthday: formData.birthday,
    }));

    navigate("/selection");
  };

  const handleInputChange = (event) => {
    const { name, value } = event.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  return (
    <div className={styles.homeContainer}>
      {/* 沉浸式互動小幫手主體區：左側 */}
      <div className={styles.assistantSection}>
        <div className={styles.videoContainer}>
          <video
            ref={videoRef}
            src="/assets/eve_sdm_talk.mp4" // 使用結構中的影片檔
            loop
            muted
            playsInline
            className={styles.assistantVideo}
            poster="/assets/eve_sdm_png" // 預設靜態圖
          />
          {/* 當說話時外圈有炫麗的粉色發光呼吸效果 */}
          <div
            className={`${styles.glowRing} ${isSpeaking ? styles.glowing : ""}`}
          ></div>
        </div>

        {/* 控制說話按鈕 */}
        <button
          className={`${styles.voicePlayBtn} ${isSpeaking ? styles.speaking : ""}`}
          onClick={handleVoiceIntro}
        >
          {isSpeaking ? "🛑 停止小幫手語音" : "🔊 聆聽小幫手引言導覽"}
        </button>

        {/* 動態字幕顯示框 */}
        {displayedSubtitle && (
          <div className={styles.subtitleBubble}>
            <p>{displayedSubtitle}</p>
          </div>
        )}
      </div>

      {/* 右側：原本的資料填寫區與按鈕 */}
      <div className={styles.formSection}>
        <div className={styles.inputWrapper}>
          <Input
            label="請輸入您的姓名"
            name="userName"
            placeholder="請輸入您的姓名"
            value={formData.userName}
            onChange={handleInputChange}
          />

          <Input
            label="請輸入您的出生年月日"
            type="date"
            name="birthday"
            value={formData.birthday}
            onChange={handleInputChange}
          />
        </div>
        <div className={styles.buttonWrapper}>
          <Button onClick={handleStart} fullWidth>
            填好了，開始選擇手術主題
          </Button>
        </div>
      </div>
    </div>
  );
};

export default Home;
